     1→// Package evolution detects performance regressions
     2→package evolution
     3→
     4→import (
     5→	"fmt"
     6→	"math"
     7→)
     8→
     9→// RegressionAlert indicates a detected performance problem
    10→type RegressionAlert struct {
    11→	Message      string
    12→	AvgNs        int64
    13→	LatestNs     int64
    14→	DegradePct   float64
    15→	PreviousNs   int64
    16→	Severity     string // "low", "medium", "high"
    17→}
    18→
    19→// RegressionDetector analyzes build history for performance issues
    20→type RegressionDetector struct {
    21→	recorder *EvolutionRecorder
    22→}
    23→
    24→// NewRegressionDetector creates a detector for an evolution recorder
    25→func NewRegressionDetector(recorder *EvolutionRecorder) *RegressionDetector {
    26→	return &RegressionDetector{
    27→		recorder: recorder,
    28→	}
    29→}
    30→
    31→// DetectRegression checks if latest build is significantly slower
    32→func (rd *RegressionDetector) DetectRegression(threshold float64) *RegressionAlert {
    33→	metrics := rd.recorder.GetMetrics()
    34→	if len(metrics) < 5 {
    35→		return nil // Need at least 5 builds for baseline
    36→	}
    37→
    38→	// Calculate average of all but last build (baseline)
    39→	var baselineSum int64
    40→	for i := 0; i < len(metrics)-1; i++ {
    41→		baselineSum += metrics[i].BuildTimeNs
    42→	}
    43→	baselineAvg := baselineSum / int64(len(metrics)-1)
    44→
    45→	latest := metrics[len(metrics)-1].BuildTimeNs
    46→
    47→	if baselineAvg == 0 {
    48→		return nil
    49→	}
    50→
    51→	ratio := float64(latest) / float64(baselineAvg)
    52→
    53→	if ratio > threshold {
    54→		degradePct := (ratio - 1.0) * 100
    55→		return &RegressionAlert{
    56→			Message:    fmt.Sprintf("Build time regression: %.2fx slower", ratio),
    57→			AvgNs:      baselineAvg,
    58→			LatestNs:   latest,
    59→			DegradePct: degradePct,
    60→			Severity:   rd.calculateSeverity(ratio),
    61→		}
    62→	}
    63→
    64→	return nil
    65→}
    66→
    67→// DetectTrendRegression detects if performance is gradually degrading
    68→func (rd *RegressionDetector) DetectTrendRegression(windowSize int) *RegressionAlert {
    69→	metrics := rd.recorder.GetMetrics()
    70→	if len(metrics) < windowSize*2 {
    71→		return nil
    72→	}
    73→
    74→	// Compare two windows: recent vs older
    75→	recentStart := len(metrics) - windowSize
    76→	olderStart := recentStart - windowSize
    77→
    78→	// Calculate average of older window
    79→	var olderSum int64
    80→	for i := olderStart; i < recentStart; i++ {
    81→		olderSum += metrics[i].BuildTimeNs
    82→	}
    83→	olderAvg := olderSum / int64(windowSize)
    84→
    85→	// Calculate average of recent window
    86→	var recentSum int64
    87→	for i := recentStart; i < len(metrics); i++ {
    88→		recentSum += metrics[i].BuildTimeNs
    89→	}
    90→	recentAvg := recentSum / int64(windowSize)
    91→
    92→	if olderAvg == 0 {
    93→		return nil
    94→	}
    95→
    96→	ratio := float64(recentAvg) / float64(olderAvg)
    97→
    98→	// Trend threshold is lower (catches gradual degradation)
    99→	const trendThreshold = 1.1 // 10% degradation
   100→
   101→	if ratio > trendThreshold {
   102→		degradePct := (ratio - 1.0) * 100
   103→		return &RegressionAlert{
   104→			Message:    fmt.Sprintf("Trending regression: %.2fx slower", ratio),
   105→			AvgNs:      olderAvg,
   106→			LatestNs:   recentAvg,
   107→			DegradePct: degradePct,
   108→			PreviousNs: olderAvg,
   109→			Severity:   rd.calculateSeverity(ratio),
   110→		}
   111→	}
   112→
   113→	return nil
   114→}
   115→
   116→// DetectOutlier finds unexpectedly slow individual builds
   117→func (rd *RegressionDetector) DetectOutlier(stdDevs float64) *RegressionAlert {
   118→	metrics := rd.recorder.GetMetrics()
   119→	if len(metrics) < 3 {
   120→		return nil
   121→	}
   122→
   123→	// Calculate mean and std dev
   124→	var sum int64
   125→	for _, m := range metrics {
   126→		sum += m.BuildTimeNs
   127→	}
   128→	mean := float64(sum) / float64(len(metrics))
   129→
   130→	var sumSq float64
   131→	for _, m := range metrics {
   132→		diff := float64(m.BuildTimeNs) - mean
   133→		sumSq += diff * diff
   134→	}
   135→	variance := sumSq / float64(len(metrics))
   136→	stdDev := math.Sqrt(variance)
   137→
   138→	latest := float64(metrics[len(metrics)-1].BuildTimeNs)
   139→	zScore := (latest - mean) / stdDev
   140→
   141→	if zScore > stdDevs {
   142→		return &RegressionAlert{
   143→			Message:    fmt.Sprintf("Outlier detected: %.1f std devs above mean", zScore),
   144→			AvgNs:      int64(mean),
   145→			LatestNs:   int64(latest),
   146→			DegradePct: ((latest - mean) / mean) * 100,
   147→			Severity:   "medium",
   148→		}
   149→	}
   150→
   151→	return nil
   152→}
   153→
   154→// calculateSeverity determines alert level based on degradation ratio
   155→func (rd *RegressionDetector) calculateSeverity(ratio float64) string {
   156→	switch {
   157→	case ratio > 2.0:
   158→		return "high"
   159→	case ratio > 1.5:
   160→		return "medium"
   161→	default:
   162→		return "low"
   163→	}
   164→}
   165→
   166→// GetHealthStatus returns overall performance health
   167→func (rd *RegressionDetector) GetHealthStatus() string {
   168→	metrics := rd.recorder.GetMetrics()
   169→	if len(metrics) == 0 {
   170→		return "unknown"
   171→	}
   172→
   173→	// Check for any regression
   174→	if rd.DetectRegression(1.2) != nil {
   175→		return "degraded"
   176→	}
   177→
   178→	// Check for trends
   179→	if rd.DetectTrendRegression(3) != nil {
   180→		return "degrading"
   181→	}
   182→
   183→	// Check for outliers
   184→	if rd.DetectOutlier(2.0) != nil {
   185→		return "unstable"
   186→	}
   187→
   188→	return "healthy"
   189→}
   190→
   191→// AnalyzeFull performs comprehensive regression analysis
   192→func (rd *RegressionDetector) AnalyzeFull() []RegressionAlert {
   193→	var alerts []RegressionAlert
   194→
   195→	// Check for absolute regression
   196→	if alert := rd.DetectRegression(1.2); alert != nil {
   197→		alerts = append(alerts, *alert)
   198→	}
   199→
   200→	// Check for trending regression
   201→	if alert := rd.DetectTrendRegression(3); alert != nil {
   202→		alerts = append(alerts, *alert)
   203→	}
   204→
   205→	// Check for outliers
   206→	if alert := rd.DetectOutlier(2.0); alert != nil {
   207→		alerts = append(alerts, *alert)
   208→	}
   209→
   210→	return alerts
   211→}
   212→

