     1→// Package parser implements an AST parser for mini FreeLang
     2→package parser
     3→
     4→import (
     5→	"fmt"
     6→	"strconv"
     7→
     8→	"github.com/user/freelang-evolving-compiler/internal/ast"
     9→	"github.com/user/freelang-evolving-compiler/internal/lexer"
    10→)
    11→
    12→type Parser struct {
    13→	l         *lexer.Lexer
    14→	curToken  ast.Token
    15→	peekToken ast.Token
    16→}
    17→
    18→// New creates a new parser for the input string
    19→func New(input string) *Parser {
    20→	l := lexer.New(input)
    21→	p := &Parser{l: l}
    22→	p.nextToken()
    23→	p.nextToken()
    24→	return p
    25→}
    26→
    27→func (p *Parser) nextToken() {
    28→	p.curToken = p.peekToken
    29→	p.peekToken = p.l.NextToken()
    30→}
    31→
    32→// ParseProgram parses a complete program
    33→func (p *Parser) ParseProgram() (*ast.Node, error) {
    34→	prog := &ast.Node{
    35→		Kind:     ast.NodeProgram,
    36→		Children: []*ast.Node{},
    37→	}
    38→
    39→	for p.curToken.Type != ast.TokenEOF {
    40→		stmt, err := p.parseStatement()
    41→		if err != nil {
    42→			return nil, err
    43→		}
    44→		if stmt != nil {
    45→			prog.Children = append(prog.Children, stmt)
    46→		}
    47→		p.skipSemicolons()
    48→	}
    49→
    50→	return prog, nil
    51→}
    52→
    53→func (p *Parser) parseStatement() (*ast.Node, error) {
    54→	switch p.curToken.Type {
    55→	case ast.TokenLet:
    56→		return p.parseLetDecl()
    57→	case ast.TokenFn:
    58→		return p.parseFnDecl()
    59→	case ast.TokenIf:
    60→		return p.parseIfStmt()
    61→	case ast.TokenFor:
    62→		return p.parseForStmt()
    63→	case ast.TokenReturn:
    64→		return p.parseReturnStmt()
    65→	case ast.TokenLBrace:
    66→		return p.parseBlockStmt()
    67→	case ast.TokenSemicolon:
    68→		p.nextToken()
    69→		return nil, nil
    70→	default:
    71→		// Try to parse as expression statement
    72→		expr, err := p.parseExpression(0)
    73→		if err != nil {
    74→			return nil, err
    75→		}
    76→		return expr, nil
    77→	}
    78→}
    79→
    80→func (p *Parser) parseLetDecl() (*ast.Node, error) {
    81→	letNode := &ast.Node{
    82→		Kind: ast.NodeLetDecl,
    83→		Line: p.curToken.Line,
    84→		Col:  p.curToken.Col,
    85→	}
    86→
    87→	p.nextToken() // consume 'let'
    88→
    89→	if p.curToken.Type != ast.TokenIdent {
    90→		return nil, fmt.Errorf("expected identifier after 'let'")
    91→	}
    92→
    93→	nameNode := &ast.Node{
    94→		Kind:  ast.NodeIdent,
    95→		Value: p.curToken.Value,
    96→		Line:  p.curToken.Line,
    97→		Col:   p.curToken.Col,
    98→	}
    99→	letNode.Children = append(letNode.Children, nameNode)
   100→
   101→	p.nextToken() // consume identifier
   102→
   103→	if p.curToken.Type != ast.TokenAssign {
   104→		return nil, fmt.Errorf("expected '=' after identifier")
   105→	}
   106→
   107→	p.nextToken() // consume '='
   108→
   109→	expr, err := p.parseExpression(0)
   110→	if err != nil {
   111→		return nil, err
   112→	}
   113→	letNode.Children = append(letNode.Children, expr)
   114→
   115→	return letNode, nil
   116→}
   117→
   118→func (p *Parser) parseFnDecl() (*ast.Node, error) {
   119→	fnNode := &ast.Node{
   120→		Kind: ast.NodeFnDecl,
   121→		Line: p.curToken.Line,
   122→		Col:  p.curToken.Col,
   123→	}
   124→
   125→	p.nextToken() // consume 'fn'
   126→
   127→	if p.curToken.Type != ast.TokenIdent {
   128→		return nil, fmt.Errorf("expected function name")
   129→	}
   130→
   131→	fnNode.Value = p.curToken.Value
   132→	p.nextToken()
   133→
   134→	if p.curToken.Type != ast.TokenLParen {
   135→		return nil, fmt.Errorf("expected '(' after function name")
   136→	}
   137→
   138→	p.nextToken()
   139→
   140→	// Parse parameters (simplified: just identifiers)
   141→	for p.curToken.Type != ast.TokenRParen {
   142→		if p.curToken.Type != ast.TokenIdent {
   143→			return nil, fmt.Errorf("expected parameter name")
   144→		}
   145→		param := &ast.Node{
   146→			Kind:  ast.NodeIdent,
   147→			Value: p.curToken.Value,
   148→		}
   149→		fnNode.Children = append(fnNode.Children, param)
   150→		p.nextToken()
   151→
   152→		if p.curToken.Type == ast.TokenColon {
   153→			p.nextToken()
   154→			if p.curToken.Type == ast.TokenIdent {
   155→				p.nextToken() // skip type for now
   156→			}
   157→		}
   158→
   159→		if p.curToken.Type == ast.TokenComma {
   160→			p.nextToken()
   161→		}
   162→	}
   163→
   164→	p.nextToken() // consume ')'
   165→
   166→	if p.curToken.Type != ast.TokenLBrace {
   167→		return nil, fmt.Errorf("expected '{' for function body")
   168→	}
   169→
   170→	body, err := p.parseBlockStmt()
   171→	if err != nil {
   172→		return nil, err
   173→	}
   174→	fnNode.Children = append(fnNode.Children, body)
   175→
   176→	return fnNode, nil
   177→}
   178→
   179→func (p *Parser) parseIfStmt() (*ast.Node, error) {
   180→	ifNode := &ast.Node{
   181→		Kind: ast.NodeIfStmt,
   182→		Line: p.curToken.Line,
   183→		Col:  p.curToken.Col,
   184→	}
   185→
   186→	p.nextToken() // consume 'if'
   187→
   188→	cond, err := p.parseExpression(0)
   189→	if err != nil {
   190→		return nil, err
   191→	}
   192→	ifNode.Children = append(ifNode.Children, cond)
   193→
   194→	if p.curToken.Type != ast.TokenLBrace {
   195→		return nil, fmt.Errorf("expected '{' after if condition")
   196→	}
   197→
   198→	body, err := p.parseBlockStmt()
   199→	if err != nil {
   200→		return nil, err
   201→	}
   202→	ifNode.Children = append(ifNode.Children, body)
   203→
   204→	return ifNode, nil
   205→}
   206→
   207→func (p *Parser) parseForStmt() (*ast.Node, error) {
   208→	forNode := &ast.Node{
   209→		Kind: ast.NodeForStmt,
   210→		Line: p.curToken.Line,
   211→		Col:  p.curToken.Col,
   212→	}
   213→
   214→	p.nextToken() // consume 'for'
   215→
   216→	if p.curToken.Type != ast.TokenIdent {
   217→		return nil, fmt.Errorf("expected iterator variable")
   218→	}
   219→
   220→	iter := &ast.Node{
   221→		Kind:  ast.NodeIdent,
   222→		Value: p.curToken.Value,
   223→	}
   224→	forNode.Children = append(forNode.Children, iter)
   225→	p.nextToken()
   226→
   227→	if p.curToken.Type != ast.TokenIn {
   228→		return nil, fmt.Errorf("expected 'in' after iterator")
   229→	}
   230→
   231→	p.nextToken()
   232→
   233→	rng, err := p.parseExpression(0)
   234→	if err != nil {
   235→		return nil, err
   236→	}
   237→	forNode.Children = append(forNode.Children, rng)
   238→
   239→	if p.curToken.Type != ast.TokenLBrace {
   240→		return nil, fmt.Errorf("expected '{' for loop body")
   241→	}
   242→
   243→	body, err := p.parseBlockStmt()
   244→	if err != nil {
   245→		return nil, err
   246→	}
   247→	forNode.Children = append(forNode.Children, body)
   248→
   249→	return forNode, nil
   250→}
   251→
   252→func (p *Parser) parseReturnStmt() (*ast.Node, error) {
   253→	retNode := &ast.Node{
   254→		Kind: ast.NodeReturn,
   255→		Line: p.curToken.Line,
   256→		Col:  p.curToken.Col,
   257→	}
   258→
   259→	p.nextToken() // consume 'return'
   260→
   261→	if p.curToken.Type == ast.TokenSemicolon || p.curToken.Type == ast.TokenRBrace {
   262→		return retNode, nil
   263→	}
   264→
   265→	expr, err := p.parseExpression(0)
   266→	if err != nil {
   267→		return nil, err
   268→	}
   269→	retNode.Children = append(retNode.Children, expr)
   270→
   271→	return retNode, nil
   272→}
   273→
   274→func (p *Parser) parseBlockStmt() (*ast.Node, error) {
   275→	block := &ast.Node{
   276→		Kind: ast.NodeBlockStmt,
   277→		Line: p.curToken.Line,
   278→		Col:  p.curToken.Col,
   279→	}
   280→
   281→	p.nextToken() // consume '{'
   282→
   283→	for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
   284→		stmt, err := p.parseStatement()
   285→		if err != nil {
   286→			return nil, err
   287→		}
   288→		if stmt != nil {
   289→			block.Children = append(block.Children, stmt)
   290→		}
   291→		p.skipSemicolons()
   292→	}
   293→
   294→	if p.curToken.Type != ast.TokenRBrace {
   295→		return nil, fmt.Errorf("expected '}'")
   296→	}
   297→
   298→	p.nextToken() // consume '}'
   299→
   300→	return block, nil
   301→}
   302→
   303→func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
   304→	left, err := p.parsePrimary()
   305→	if err != nil {
   306→		return nil, err
   307→	}
   308→
   309→	for prec < p.peekPrecedence() {
   310→		p.nextToken()
   311→		left, err = p.parseInfix(left)
   312→		if err != nil {
   313→			return nil, err
   314→		}
   315→	}
   316→
   317→	return left, nil
   318→}
   319→
   320→func (p *Parser) parsePrimary() (*ast.Node, error) {
   321→	switch p.curToken.Type {
   322→	case ast.TokenInt:
   323→		node := &ast.Node{
   324→			Kind:  ast.NodeIntLit,
   325→			Value: p.curToken.Value,
   326→			Line:  p.curToken.Line,
   327→			Col:   p.curToken.Col,
   328→		}
   329→		return node, nil
   330→
   331→	case ast.TokenIdent:
   332→		node := &ast.Node{
   333→			Kind:  ast.NodeIdent,
   334→			Value: p.curToken.Value,
   335→			Line:  p.curToken.Line,
   336→			Col:   p.curToken.Col,
   337→		}
   338→		return node, nil
   339→
   340→	case ast.TokenLParen:
   341→		p.nextToken()
   342→		expr, err := p.parseExpression(0)
   343→		if err != nil {
   344→			return nil, err
   345→		}
   346→		if p.curToken.Type != ast.TokenRParen {
   347→			return nil, fmt.Errorf("expected ')'")
   348→		}
   349→		return expr, nil
   350→
   351→	default:
   352→		return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
   353→	}
   354→}
   355→
   356→func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
   357→	node := &ast.Node{
   358→		Kind: ast.NodeBinaryExpr,
   359→		Line: p.curToken.Line,
   360→		Col:  p.curToken.Col,
   361→		Value: p.curToken.Value,
   362→		Children: []*ast.Node{left},
   363→	}
   364→
   365→	prec := p.curPrecedence()
   366→	p.nextToken()
   367→
   368→	right, err := p.parseExpression(prec)
   369→	if err != nil {
   370→		return nil, err
   371→	}
   372→	node.Children = append(node.Children, right)
   373→
   374→	// Handle function calls
   375→	if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
   376→		call := &ast.Node{
   377→			Kind:  ast.NodeCallExpr,
   378→			Value: left.Value,
   379→		}
   380→		p.nextToken() // consume '('
   381→		for p.curToken.Type != ast.TokenRParen {
   382→			arg, err := p.parseExpression(0)
   383→			if err != nil {
   384→				return nil, err
   385→			}
   386→			call.Children = append(call.Children, arg)
   387→			if p.curToken.Type == ast.TokenComma {
   388→				p.nextToken()
   389→			}
   390→		}
   391→		p.nextToken() // consume ')'
   392→		return call, nil
   393→	}
   394→
   395→	return node, nil
   396→}
   397→
   398→func (p *Parser) peekPrecedence() int {
   399→	return precedence(p.peekToken.Type)
   400→}
   401→
   402→func (p *Parser) curPrecedence() int {
   403→	return precedence(p.curToken.Type)
   404→}
   405→
   406→func precedence(tok ast.TokenType) int {
   407→	switch tok {
   408→	case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
   409→		return 1
   410→	case ast.TokenPlus, ast.TokenMinus:
   411→		return 2
   412→	case ast.TokenStar, ast.TokenSlash:
   413→		return 3
   414→	case ast.TokenDotDot:
   415→		return 4
   416→	default:
   417→		return 0
   418→	}
   419→}
   420→
   421→func (p *Parser) skipSemicolons() {
   422→	for p.curToken.Type == ast.TokenSemicolon {
   423→		p.nextToken()
   424→	}
   425→}
