    19→// TestRecordBuild validates recording a single build
    20→func TestRecordBuild(t *testing.T) {
    21→	rec := NewEvolutionRecorder()
    22→
    23→	metric := rec.RecordBuild(1000000, []string{"ConstantFolding"}, 512, "abc123")
    24→
    25→	if metric.BuildID == "" {
    26→		t.Errorf("expected build ID")
    27→	}
    28→	if metric.BuildTimeNs != 1000000 {
    29→		t.Errorf("expected 1000000ns, got %d", metric.BuildTimeNs)
    30→	}
    31→	if metric.OptsPassed != 1 {
    32→		t.Errorf("expected 1 opt, got %d", metric.OptsPassed)
    33→	}
    34→	if metric.CodeSizeBy != 512 {
    35→		t.Errorf("expected 512 bytes, got %d", metric.CodeSizeBy)
    36→	}
    37→}
